Definition pf_stops : list Z := [0x179c4].
Definition pf_fuel : nat := 3000.

(* [comment removed for export] *)
Definition pf_regions : list sregion :=
  [(SA (EVar 0) (-1056), 1056); (SA (ELit 0) 0x395f8, 4); (SA (ELit 0) 0x39620, 8); (SA (EVar 1) 0, 2)].

(* [comment removed for export] *)
Section VP0.
  Context {fx : FPState}.   (* [comment removed for export] *)
Definition pf_post (regs : bvmap 5 word) (mem rom : word -> option byte) (sp : word) (w : Z) : Prop :=
  exists regs' mem',
    msteps RSEGS (mkst regs (Z_to_bv 64 0x17a70) mem rom) (mkst regs' (Z_to_bv 64 0x179c4) mem' rom)
    /\ keeps_cs regs regs'
    /\ frame_mod mem mem' [(Z_to_bv 64 (bv_unsigned sp - 1056), 1056); (Z_to_bv 64 0x395f8, 4);
                          (Z_to_bv 64 0x39620, 8); (Z_to_bv 64 w, 2)]
    /\ rdn RSEGS mem' (Z_to_bv 64 w) 2 = Some [Z_to_bv 8 0x30; Z_to_bv 8 0x0a]
    /\ rdn RSEGS mem' (Z_to_bv 64 0x39620) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 (w + 2)))
    /\ rdn RSEGS mem' (Z_to_bv 64 0x395f8) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 5)).
End VP0.

